import sys
from bisect import bisect_left, insort

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    q = int(input_data[0])

    history = []
    current_map = {}
    sorted_priorities = []

    def get_state(day_index):
        if day_index == 0:
            return {}, []
        return history[day_index - 1]

    def restore_state(target_day):
        nonlocal current_map, sorted_priorities
        if target_day == 0:
            current_map = {}
            sorted_priorities = []
        else:
            current_map, sorted_priorities = history[target_day - 1]

    for i in range(1, q + 1):
        parts = input_data[i].split()
        op = parts[0]

        if op == 'set':
            assign_name = parts[1]
            priority = int(parts[2])

            if assign_name in current_map:
                old_priority = current_map[assign_name]
                idx = sorted_priorities.index(old_priority)
                sorted_priorities.pop(idx)

            current_map[assign_name] = priority
            insort(sorted_priorities, priority)

            history.append((dict(current_map), list(sorted_priorities)))

        elif op == 'remove':
            assign_name = parts[1]
            if assign_name in current_map:
                priority = current_map[assign_name]
                del current_map[assign_name]
                idx = sorted_priorities.index(priority)
                sorted_priorities.pop(idx)

            history.append((dict(current_map), list(sorted_priorities)));

        elif op == 'query':
            assign_name = parts[1]
            if assign_name not in current_map:
                print(-1)
            else:
                priority = current_map[assign_name]
                count = bisect_left(sorted_priorities, priority)
                print(count)
            sys.stdout.flush()

            history.append((dict(current_map), list(sorted_priorities)))

        elif op == 'undo':
            d = int(parts[1])
            restore_state(d)
            history.append((dict(current_map), list(sorted_priorities)))

if __name__ == "__main__":
    main()
